74	        if (owner == null) {
75	            return null;
76	        }
77	        String title = owner.getTitle();
78	        if (title == null || title.isEmpty()) {
79	            return owner.getLastName();
80	        }
81	        return title + " " + owner.getLastName();
82	    }
83	
84	    /**
85	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
86	     * last names, as required by the API's read-only {@code displayName} field.
87	     *
88	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
89	     * applied only where referenced via {@code qualifiedByName}.
90	     */
91	    @Named("formatDisplayName")
92	    default String formatDisplayName(Owner owner) {
93	        if (owner == null) {
94	            return null;
95	        }
96	        return owner.getLastName() + ", " + owner.getFirstName();
97	    }
98	
99	    /**
100	     * Formats an owner's initials as the upper-cased first letters of the first and last
101	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
102	     * API's read-only {@code initials} field.
103	     *
104	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
105	     * applied only where referenced via {@code qualifiedByName}.
106	     */
107	    @Named("formatInitials")
108	    default String formatInitials(Owner owner) {
109	        if (owner == null) {
110	            return null;
111	        }
112	        return initial(owner.getFirstName()) + initial(owner.getLastName());
113	    }
114	
115	    /**
116	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
117	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
118	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
119	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
120	     * telephone is present.
121	     *
122	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
123	     * applied only where referenced via {@code qualifiedByName}.
124	     */
125	    @Named("formatTelephoneDisplay")
126	    default String formatTelephoneDisplay(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
131	    }
132	
133	    /**
134	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
135	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
136	     * {@code YY} is the last two digits of the fiscal year (the fiscal year starting on
137	     * 1 July) of the business-day-adjusted registration date (e.g. {@code 'NSW-1A2B3C4D-M26'}),
138	     * as required by the API's read-only {@code membershipNumber} field. Returns {@code null}
139	     * when either the customer code or registration date is absent.
140	     *
141	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
142	     * applied only where referenced via {@code qualifiedByName}.
143	     */
144	    @Named("formatMembershipNumber")
145	    default String formatMembershipNumber(Owner owner) {
146	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
147	            return null;
148	        }
149	        return String.format("%s-M%02d", owner.getCustomerCode(),
150	            fiscalYearStart(owner.getRegistrationDate()) % 100);
151	    }
152	
153	    /**
154	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, as required by the API's read-only
155	     * {@code fiscalYear} field: the fiscal year of the business-day-adjusted registration date,
156	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the
157	     * calendar year in which that fiscal year begins (so a registration date of
158	     * {@code 2026-10-02} yields {@code 'FY26'} and {@code 2026-03-02} yields {@code 'FY25'}).
159	     * Returns {@code null} when no registration date is present.
160	     *
161	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
162	     * applied only where referenced via {@code qualifiedByName}.
163	     */
164	    @Named("formatFiscalYear")
165	    default String formatFiscalYear(Owner owner) {
166	        if (owner == null || owner.getRegistrationDate() == null) {
167	            return null;
168	        }
169	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
170	    }
171	
172	    /**
173	     * Returns the calendar year in which the fiscal year containing {@code date} begins. The
174	     * fiscal year starts on 1 July, so dates in July through December belong to the fiscal year
175	     * starting in their own calendar year, while dates in January through June belong to the
176	     * fiscal year that started in the previous calendar year.
177	     */
178	    private static int fiscalYearStart(LocalDate date) {
179	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
180	    }
181	
182	    /**
183	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
184	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
185	     * code. Returns {@code null} when the customer code is absent.
186	     *
187	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
188	     * applied only where referenced via {@code qualifiedByName}.
189	     */
190	    @Named("formatCheckDigit")
191	    default Integer formatCheckDigit(Owner owner) {
192	        if (owner == null || owner.getCustomerCode() == null) {
193	            return null;
194	        }
195	        return LuhnCheckDigit.compute(owner.getCustomerCode());
196	    }
197	
198	    /**
199	     * Computes an owner's membership points, as required by the API's read-only
200	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
201	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
202	     * of 3 or more members, plus 3 when the owner's tenure spans at least one elapsed fiscal year
203	     * (the registration date's fiscal year precedes the current fiscal year, the fiscal year
204	     * starting on 1 July).
205	     *
206	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
207	     * applied only where referenced via {@code qualifiedByName}.
208	     */
209	    @Named("formatMembershipPoints")
210	    default Integer formatMembershipPoints(Owner owner) {
211	        if (owner == null) {
212	            return null;
213	        }
214	        int points = 0;
215	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
216	            points += 2;
217	        }
218	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
219	            points += 1;
220	        }
221	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
222	            points += 2;
223	        }
224	        if (owner.getRegistrationDate() != null
225	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
226	            points += 3;
227	        }
228	        return points;
229	    }
230	
231	    /**
232	     * Derives an owner's membership level, as required by the API's read-only
233	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
234	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
235	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
236	     *
237	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
238	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
239	     * to record the membership level on the create audit line).
240	     */
241	    @Named("formatMembershipLevel")
242	    default Integer formatMembershipLevel(Owner owner) {
243	        if (owner == null) {
244	            return null;
245	        }
246	        int points = formatMembershipPoints(owner);
247	        if (points <= 1) {
248	            return 1;
249	        }
250	        if (points <= 3) {
251	            return 2;
252	        }
253	        if (points <= 5) {
254	            return 3;
255	        }
256	        return 4;
257	    }
258	
259	    /**
260	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
261	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
262	     * locality is read from the same region-and-hash identity that the customer code encodes.
263	     * When no customer code is present (e.g. an owner that predates the code), the region is
264	     * resolved directly from the postcode (falling back to the city-to-region table, else
265	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
266	     *
267	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
268	     * applied only where referenced via {@code qualifiedByName}.
269	     */
270	    @Named("formatLocality")
271	    default String formatLocality(Owner owner) {
272	        if (owner == null) {
273	            return null;
274	        }
275	        String customerCode = owner.getCustomerCode();
276	        if (customerCode != null) {
277	            int dash = customerCode.indexOf('-');
278	            if (dash > 0) {
279	                return customerCode.substring(0, dash);
280	            }
281	        }
282	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
283	    }
284	
285	    /**
286	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
287	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
288	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
289	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
290	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
291	     *
292	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
293	     * applied only where referenced via {@code qualifiedByName}.
294	     */
295	    @Named("formatTimezone")
296	    default String formatTimezone(Owner owner) {
297	        if (owner == null) {
298	            return null;
299	        }
300	        return LocalityResolver.timezone(formatLocality(owner));
301	    }
302	
303	    /**
304	     * Derives an owner's preferred contact channel, as required by the API's read-only
305	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
306	     * otherwise {@code 'PHONE'}.
307	     *
308	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
309	     * applied only where referenced via {@code qualifiedByName}.
310	     */
311	    @Named("formatContactPreference")
312	    default String formatContactPreference(Owner owner) {
313	        if (owner == null) {
314	            return null;
315	        }
316	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
317	    }
318	
319	    /**
320	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
321	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
322	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
323	     * no birth date was supplied (so the field is absent), or when no registration date is yet
324	     * known against which to compute the age.
325	     *
326	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
327	     * applied only where referenced via {@code qualifiedByName}.
328	     */
329	    @Named("formatAgeBand")
330	    default String formatAgeBand(Owner owner) {
331	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
332	            return null;
333	        }
334	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
335	        if (age < 18) {
336	            return "MINOR";
337	        }
338	        if (age < 65) {
339	            return "ADULT";
340	        }
341	        return "SENIOR";
342	    }
343	
344	    private static String initial(String name) {
345	        if (name == null || name.isEmpty()) {
346	            return "";
347	        }
348	        return Character.toUpperCase(name.charAt(0)) + ".";
349	    }
350	
351	    Owner toOwner(OwnerDto ownerDto);
352	
353	    @Mapping(target = "id", ignore = true)
354	    @Mapping(target = "pets", ignore = true)
355	    @Mapping(target = "addressLine1", ignore = true)
356	    @Mapping(target = "addressLine2", ignore = true)
357	    @Mapping(target = "address", ignore = true)
358	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
359	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
360	    @Mapping(target = "title", source = "title", qualifiedByName = "mapTitle")
361	    Owner toOwner(OwnerFieldsDto ownerDto);
362	
363	    /**
364	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
365	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
366	     * title was supplied. This is the single place the inbound title conversion lives: it runs
367	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
368	     * update path, keeping both consistent.
369	     *
370	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
371	     * applied only where referenced via {@code qualifiedByName}.
372	     */
373	    @Named("mapTitle")
374	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
375	        return title == null ? null : title.getValue();
376	    }
377	
378	    /**
379	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
380	     * normalizing each. This is the single place the structured-field normalization rule lives: it
381	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
382	     * called directly on the update path to keep both create and update consistent.
383	     *
384	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
385	     * {@code address} is set to the {@link #composeAddress composed} effective address.
386	     */
387	    @AfterMapping
388	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
389	        if (ownerDto == null) {
390	            return;
391	        }
392	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
393	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
394	        owner.setAddress(composeAddress(ownerDto));
395	    }
396	
397	    /**
398	     * Composes the effective, normalized postal address for an owner from the supplied fields,
399	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
400	     * present, the result is the normalized {@code addressLine1} with the normalized
401	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
402	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
403	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
404	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
405	     */
406	    default String composeAddress(OwnerFieldsDto ownerDto) {
407	        if (ownerDto == null) {
408	            return null;
409	        }
410	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
411	        if (line1 != null && !line1.isEmpty()) {
412	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
413	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
414	        }
415	        return normalizeAddress(ownerDto.getAddress());
416	    }
417	
418	    /**
419	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
420	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
421	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
422	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
423	     * {@code '12 MAIN STREET'}.
424	     *
425	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
426	     * only where referenced via {@code qualifiedByName}.
427	     */
428	    @Named("normalizeAddress")
429	    default String normalizeAddress(String address) {
430	        return AddressNormalizer.normalize(address);
431	    }
432	
433	    /**
434	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
435	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
436	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
437	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
438	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
439	     *
440	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
441	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
442	     *
443	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
444	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
445	     */
446	    @Named("normalizeTelephone")
447	    default String normalizeTelephone(String telephone) {
448	        return TelephoneNormalizer.toE164(telephone);
449	    }
450	
451	    /**
452	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
453	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
454	     * guarantees any value present is a syntactically valid address.
455	     *
456	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
457	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
458	     * e.g. on update).
459	     */
460	    @Named("normalizeEmail")
461	    default String normalizeEmail(String email) {
462	        return email == null ? null : email.toLowerCase(Locale.ROOT);
463	    }
464	
465	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
466	
467	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
468	
469	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
470	        OwnerPageDto ownerPageDto = new OwnerPageDto();
471	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
472	        ownerPageDto.setPage(ownerPage.getNumber());
473	        ownerPageDto.setSize(ownerPage.getSize());
474	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
475	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
476	        return ownerPageDto;
477	    }
478	}
